// Construit la requete multimodale pour Gemini.
// Les 6 images sont lues dans l'ordre des champs du formulaire = U,R,F,D,L,B.
const FACE_ORDER = ['U','R','F','D','L','B'];
const item = $input.first();
const binKeys = Object.keys(item.binary || {});
if (binKeys.length < 6) {
  throw new Error('Il faut 6 images (une par face). Recu: ' + binKeys.length);
}

const prompt = `Tu es un detecteur de couleurs pour un Rubik's Cube 3x3.
Je te donne 6 images, une par face, dans l'ordre: U (haut), R (droite), F (avant), D (bas), L (gauche), B (arriere).
Pour CHAQUE face, lis les 9 stickers de GAUCHE a DROITE puis de HAUT en BAS (comme la lecture).
Utilise UNIQUEMENT ces noms de couleur en minuscule: white, yellow, red, orange, blue, green.
Reponds STRICTEMENT en JSON, sans texte autour, au format exact:
{\"faces\":{\"U\":[9 couleurs],\"R\":[9],\"F\":[9],\"D\":[9],\"L\":[9],\"B\":[9]}}`;

const parts = [{ text: prompt }];
for (let i = 0; i < 6; i++) {
  const key = binKeys[i];
  const buffer = await this.helpers.getBinaryDataBuffer(0, key);
  const bin = item.binary[key];
  parts.push({ text: 'Image de la face ' + FACE_ORDER[i] + ' :' });
  parts.push({ inline_data: { mime_type: bin.mimeType || 'image/jpeg', data: buffer.toString('base64') } });
}

const body = {
  contents: [{ parts }],
  generationConfig: { temperature: 0, responseMimeType: 'application/json' }
};
return [{ json: { body } }];

// Extrait l'objet 'faces' du JSON renvoye par Gemini.
const resp = $input.first().json;
const text = resp?.candidates?.[0]?.content?.parts?.[0]?.text;
if (!text) {
  throw new Error('Reponse Gemini vide ou bloquee: ' + JSON.stringify(resp).slice(0, 600));
}
let parsed;
try {
  parsed = JSON.parse(text);
} catch (e) {
  const m = text.match(/\{[\s\S]*\}/);
  if (!m) throw new Error('JSON introuvable dans la reponse: ' + text.slice(0, 300));
  parsed = JSON.parse(m[0]);
}
const faces = parsed.faces || parsed;
return [{ json: { faces } }];

// Met en forme la solution pour l'humain.
const r = $input.first().json;
if (r.error) {
  return [{ json: { titre: 'Erreur', message: 'Probleme: ' + r.error } }];
}
const LABEL = {
  'U': 'Tourner la face du HAUT',
  'R': 'Tourner la face de DROITE',
  'F': 'Tourner la face AVANT',
  'D': 'Tourner la face du BAS',
  'L': 'Tourner la face de GAUCHE',
  'B': 'Tourner la face ARRIERE'
};
const SENS = (m) => m.includes("'") ? 'sens anti-horaire (90 gauche)' : (m.includes('2') ? '2 fois (180)' : 'sens horaire (90 droite)');
const moves = r.moves || [];
const etapes = moves.map((m, i) => {
  const face = m[0];
  return (i + 1) + '. ' + m + '  ->  ' + LABEL[face] + ', ' + SENS(m);
});
const message = 'Solution (' + r.move_count + ' mouvements):\n\n' +
  r.solution + '\n\n--- Etape par etape ---\n' + etapes.join('\n');
return [{ json: { titre: 'Cube resolu en ' + r.move_count + ' mouvements', message, solution: r.solution } }];

// Groq Vision - 2 lots de 3 images (limite Groq: 5 images max par appel)
const FACE_ORDER = ['U','R','F','D','L','B'];
const item = $input.first();
const binKeys = Object.keys(item.binary || {});
if (binKeys.length < 6) {
  throw new Error('Il faut 6 images (une par face). Recu: ' + binKeys.length);
}

// Clé API insérée directement pour éviter l'erreur n8n "access to env vars denied"
const GROQ_KEY = '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';
const MODEL = 'meta-llama/llama-4-scout-17b-16e-instruct';

// Charger toutes les images en base64
const images = [];
for (let i = 0; i < 6; i++) {
  const key = binKeys[i];
  const buffer = await this.helpers.getBinaryDataBuffer(0, key);
  const bin = item.binary[key];
  images.push({ b64: buffer.toString('base64'), mime: bin.mimeType || 'image/jpeg' });
}

// Appel Groq pour un lot de faces
const callGroq = async (faceNames, imgs) => {
  const prompt = `Tu es un robot d'analyse de pixels ultra-précis pour un Rubik's Cube.
Voici ${imgs.length} images de faces dans cet ordre : ${faceNames.join(', ')}.
Pour CHAQUE face, tu DOIS analyser strictement une grille de 3x3 (9 carrés).
Lis les carrés EXACTEMENT dans cet ordre pour chaque face :
1. Haut-Gauche
2. Haut-Milieu
3. Haut-Droite
4. Milieu-Gauche
5. Centre
6. Milieu-Droite
7. Bas-Gauche
8. Bas-Milieu
9. Bas-Droite

Utilise UNIQUEMENT ces mots en anglais et en minuscule : white, yellow, red, orange, blue, green.
NE FAIS AUCUNE ERREUR.
Reponds STRICTEMENT en format JSON valide, par exemple : {\"faces\":{\"${faceNames[0]}\":[\"white\",\"red\",\"green\",\"blue\",\"yellow\",\"orange\",\"white\",\"red\",\"blue\"], ...}}`;

  const content = [{ type: 'text', text: prompt }];
  for (const img of imgs) {
    content.push({ type: 'image_url', image_url: { url: 'data:' + img.mime + ';base64,' + img.b64 } });
  }

  const resp = await this.helpers.httpRequest({
    method: 'POST',
    url: 'https://api.groq.com/openai/v1/chat/completions',
    headers: { 'Authorization': 'Bearer ' + GROQ_KEY, 'Content-Type': 'application/json' },
    body: JSON.stringify({
      model: MODEL,
      messages: [{ role: 'user', content }],
      response_format: { type: 'json_object' },
      temperature: 0
    })
  });

  const text = resp?.choices?.[0]?.message?.content;
  if (!text) throw new Error('Reponse Groq vide: ' + JSON.stringify(resp).slice(0, 300));
  let parsed;
  try { parsed = JSON.parse(text); } catch(e) {
    const m = text.match(/\{[\s\S]*\}/); if (!m) throw new Error('JSON introuvable: ' + text.slice(0,300));
    parsed = JSON.parse(m[0]);
  }
  return parsed.faces || parsed;
};

// Lot 1: U, R, F - Lot 2: D, L, B
const [faces1, faces2] = await Promise.all([
  callGroq(['U','R','F'], images.slice(0,3)),
  callGroq(['D','L','B'], images.slice(3,6))
]);

const faces = { ...faces1, ...faces2 };
return [{ json: { faces } }];
